const abbreviations = new Set([
  'mr.',
  'mrs.',
  'ms.',
  'dr.',
  'prof.',
  'sr.',
  'jr.',
  'st.',
  'vs.',
  'fig.',
  'no.',
  'dept.',
  'inc.',
  'ltd.',
  'co.'
]);

function isProtectedPeriod(text, index) {
  const previous = text[index - 1] || '';
  const next = text[index + 1] || '';

  if (/\d/u.test(previous) && /\d/u.test(next)) {
    return true;
  }

  if (/[\p{L}\p{N}]/u.test(previous) && /[\p{L}\p{N}]/u.test(next)) {
    return true;
  }

  let start = index;
  while (start > 0 && /[\p{L}.]/u.test(text[start - 1])) {
    start -= 1;
  }

  const token = text.slice(start, index + 1).toLowerCase();
  return abbreviations.has(token) || /^(?:\p{L}\.){2,}$/u.test(token);
}

function process(data) {
  const text = data && data.selection;
  if (typeof text !== 'string') {
    throw new TypeError('selection must be a string');
  }

  let output = '';
  let capitalizeNext = true;

  for (let index = 0; index < text.length; ) {
    const character = String.fromCodePoint(text.codePointAt(index));
    const hasCase = character.toUpperCase() !== character.toLowerCase();

    if (capitalizeNext && hasCase) {
      output += character.toUpperCase();
      capitalizeNext = false;
    } else {
      output += character;
    }

    if ('!?。！？\n\r\u2028\u2029'.includes(character)) {
      capitalizeNext = true;
    } else if (character === '.' && !isProtectedPeriod(text, index)) {
      capitalizeNext = true;
    }

    index += character.length;
  }

  return output;
}
